// Deterministic validation. The model reads the document; this node decides
// whether a human needs to look at it. Arithmetic is never left to the model.

const TOLERANCE = 0.02; // pennies of rounding drift we accept

function toIsoDate(raw) {
  if (!raw) return null;
  const s = String(raw).trim();

  // 14/07/2026 or 14-07-26  (UK order: day first)
  const numeric = s.match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{2,4})$/);
  if (numeric) {
    let [, d, m, y] = numeric;
    if (y.length === 2) y = '20' + y;
    const iso = `${y}-${m.padStart(2, '0')}-${d.padStart(2, '0')}`;
    return Number.isNaN(Date.parse(iso)) ? null : iso;
  }

  // 09 Jul 2026 / 1 July 2026
  // Formatted from LOCAL date parts, never toISOString(): under BST a date
  // parsed as local midnight converts back to 23:00 the previous day in UTC,
  // which silently books an invoice into the wrong period.
  const parsed = new Date(s);
  if (!Number.isNaN(parsed.getTime())) {
    const y = parsed.getFullYear();
    const mo = String(parsed.getMonth() + 1).padStart(2, '0');
    const day = String(parsed.getDate()).padStart(2, '0');
    return `${y}-${mo}-${day}`;
  }

  return null;
}

const out = [];

for (const item of $input.all()) {
  const d = item.json;
  const reasons = [];

  const net = Number(d.net_amount) || 0;
  const vat = Number(d.vat_amount) || 0;
  const gross = Number(d.gross_amount) || 0;

  // 1. Does the arithmetic hold?
  if (gross > 0 && net > 0 && Math.abs(net + vat - gross) > TOLERANCE) {
    reasons.push(`Totals do not reconcile: ${net.toFixed(2)} + ${vat.toFixed(2)} != ${gross.toFixed(2)}`);
  }

  // 2. Reconstruct net where the document only showed gross and VAT.
  let netFinal = net;
  if (net === 0 && gross > 0) {
    netFinal = Number((gross - vat).toFixed(2));
    reasons.push('Net not stated on document; derived as gross minus VAT');
  }

  // 3. Is the VAT rate plausible for a UK document?
  if (netFinal > 0 && vat > 0) {
    const rate = (vat / netFinal) * 100;
    const plausible = [0, 5, 20].some(r => Math.abs(rate - r) < 1.5);
    if (!plausible) reasons.push(`Unusual VAT rate: ${rate.toFixed(1)}%`);
  }

  // 4. Date must be parseable into something an accounts system will accept.
  const isoDate = toIsoDate(d.issue_date);
  if (!isoDate) reasons.push(`Unreadable date: "${d.issue_date}"`);

  // 5. Required fields actually present.
  if (!d.supplier_name) reasons.push('Supplier name missing');
  if (!gross) reasons.push('Gross total missing');
  if (!d.document_reference) reasons.push('No document reference (common on till receipts)');

  out.push({
    json: {
      supplier: d.supplier_name || null,
      reference: d.document_reference || null,
      date: isoDate,
      date_raw: d.issue_date || null,
      currency: (d.currency || 'GBP').toUpperCase(),
      net: netFinal,
      vat,
      gross,
      source: item.json.source ?? $('Load Sample Documents').all()[out.length]?.json?.source ?? null,
      review_required: reasons.length > 0,
      review_reasons: reasons
    }
  });
}

return out;
